  quiz: [
  {q:"A life insurance policy's incontestability clause typically prevents the insurer from contesting a claim after how long?",
   opts:["6 months", "1 year", "2 years", "5 years"], a:2,
   explanation:"Two years from issue is the standard, and it is set by state statute rather than by the insurer. After it runs, the insurer can no longer void the policy for a misstatement on the application — fraud aside, and even that exception varies by state."},
  {q:"Which of these best describes a 'free look' period?",
   opts:["A window to cancel a new policy for a full refund", "The time an insurer has to pay a claim", "A grace period for a missed premium", "A waiting period before coverage starts"], a:0,
   explanation:"The free look starts on delivery, not on application. The length is one of the most state-variable numbers on the exam — commonly 10 days, but longer for replacement policies and for senior buyers in several states."},
  {q:"In an HMO plan, a policyholder typically must:",
   opts:["Pay no premium at all", "Choose a primary care physician and use in-network providers", "Use any provider nationwide with no referral", "Only be covered for emergencies"], a:1,
   explanation:"The gatekeeper model is what distinguishes an HMO. A PPO drops the referral requirement and pays something out of network; an HMO generally pays nothing out of network except in an emergency."},
  {q:"Adverse selection refers to:",
   opts:["An insurer selecting only healthy applicants", "Higher-risk individuals being more likely to seek coverage", "A policy lapsing for nonpayment", "A state denying a license application"], a:1,
   explanation:"Adverse selection runs toward the insurer, not away from it. Underwriting, waiting periods and pre-existing condition provisions all exist to blunt it."},
  {q:"A whole life policy's cash value grows:",
   opts:["Only if the stock market rises", "On a tax-deferred basis over the life of the policy", "Only after the insured turns 65", "It never grows"], a:1,
   explanation:"Growth is guaranteed and tax-deferred. Tax is only triggered on surrender above basis, or by a loan on a policy that has become a modified endowment contract."},
  {q:"Under a 1035 exchange, a policyholder may exchange:",
   opts:["An annuity for a life insurance policy", "A life insurance policy for an annuity", "A health policy for a life policy", "Any policy for any other policy"], a:1,
   explanation:"Section 1035 runs one way down the ladder. Life to life, life to annuity and annuity to annuity all qualify; annuity to life does not, because it would convert taxable gain into a tax-free death benefit."},
  {q:"An agent persuades a client to drop an existing policy and buy a new one by misrepresenting the terms of the old one. This is:",
   opts:["Churning", "Twisting", "Rebating", "Commingling"], a:1,
   explanation:"Twisting is inducing a replacement through misrepresentation, and it is a named unfair trade practice in every state's insurance code. Churning is the same conduct within one insurer's own book; rebating is giving away part of the commission."},
  {q:"If a permanent policy lapses and the owner takes no action, most policies apply which nonforfeiture option by default?",
   opts:["Cash surrender", "Extended term insurance", "Reduced paid-up insurance", "The policy simply terminates"], a:1,
   explanation:"Extended term is the usual automatic default: the cash value buys term coverage at the full face amount for as long as it will last. Reduced paid-up keeps coverage for life at a smaller face amount, but the owner has to elect it."},
  ],

  flashcards: [
  {f:"Insurable Interest", b:"A financial or emotional stake in the continued life, health, or existence of the insured — required for a policy to be valid."},
  {f:"Grace Period", b:"The window (commonly 30–31 days) after a missed premium during which the policy stays in force."},
  {f:"Contestability Period", b:"The period (typically 2 years) during which an insurer can investigate and contest a claim based on application misstatements."},
  {f:"Free Look Period", b:"A set number of days after delivery during which the policyholder can cancel a new policy for a full refund."},
  {f:"Reinstatement", b:"Restoring a lapsed policy to force, usually requiring proof of insurability and payment of back premiums."},
  {f:"Coordination of Benefits", b:"Rules that determine payment order when a person is covered by more than one health plan."},
  {f:"Nonforfeiture Options", b:"Choices a policyholder has for the cash value of a lapsing permanent policy: cash surrender, extended term, or reduced paid-up."},
  {f:"Twisting", b:"An unfair trade practice — misrepresenting a policy to induce a replacement that isn't in the client's interest."},
  {f:"Adverse Selection", b:"The tendency of higher-risk individuals to seek insurance more actively than lower-risk ones — the reason underwriting and waiting periods exist."},
  {f:"1035 Exchange", b:"A tax-free exchange of one life insurance or annuity contract for another. Life to annuity is permitted; annuity to life is not."},
  {f:"Waiver of Premium", b:"A rider that keeps a policy in force without further premium payments if the insured becomes totally disabled, usually after a waiting period."},
  {f:"Elimination Period", b:"The waiting period between the onset of a disability and the first benefit payment — a deductible measured in time rather than dollars."},
  {f:"Modified Endowment Contract", b:"A life policy funded faster than the 7-pay test allows. Death benefit stays tax-free, but loans and withdrawals are taxed gain-first with a possible penalty."},
  ],

